const chronologicalRange = {
  message: "The time range ends before it starts.",
  path: ["until"],
} as const;

function rangeIsOrdered(value: {
  since?: string;
  until?: string;
}): boolean {
  if (value.since === undefined || value.until === undefined) return true;
  return Date.parse(value.since) <= Date.parse(value.until);
}

export const activityFilterSchema = z
  .object({
    orgId: orgIdSchema,
    action: z.array(activityActionSchema).optional(),
    actorId: userIdSchema.optional(),
    projectId: projectIdSchema.optional(),
    subjectKind: activitySubjectKindSchema.optional(),
    since: isoTimestampSchema.optional(),
    until: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .refine(rangeIsOrdered, chronologicalRange);

export const exportActivitySchema = z
  .object({
    orgId: orgIdSchema,
    since: isoTimestampSchema,
    until: isoTimestampSchema,
    format: z.enum(["csv", "json"]).default("csv"),
  })
  .refine(rangeIsOrdered, chronologicalRange);

/** Refuses a filter whose end is strictly earlier than its start. */
export function assertActivityRange(
  since?: string,
  until?: string,
): void {
  z.object({ since: z.string().optional(), until: z.string().optional() })
    .refine(rangeIsOrdered, chronologicalRange)
    .parse({ since, until });
}

