/** Project an issue belonged to, preferring the id carried on the event. */
async function projectForIssue(
  orgId: OrgId,
  issueId: IssueId,
  explicit: ProjectId | null | undefined,
): Promise<ProjectId | null> {
  if (explicit) return explicit;
  const issue = await issueRepo.findIssueById(orgId, issueId);
  return issue?.projectId ?? null;
}

